// Everything the invoice needs is worked out here, once, so the HTML stays a layout
// and not a calculator: per-line amounts, subtotal, VAT, grand total, and the dates
// that follow from your payment terms.
const item = $input.first().json;
const body = item.body || {};

const currency = String(body.currency || item.default_currency || 'EUR').toUpperCase();
const vatPercent = Number(item.vat_percent) || 0;
const termsDays = Number(item.payment_terms_days) || 14;
const money = (n) => currency + ' ' + n.toFixed(2);

const rows = (body.line_items || []).map((li) => {
  const quantity = Number(li.quantity) || 0;
  const unitPrice = Number(li.unit_price) || 0;
  const amount = Math.round(quantity * unitPrice * 100) / 100;
  return {
    description: String(li.description || 'Item'),
    quantity,
    unit_display: money(unitPrice),
    amount,
    amount_display: money(amount),
  };
});

const subtotal = Math.round(rows.reduce((sum, r) => sum + r.amount, 0) * 100) / 100;
const vat = Math.round(subtotal * vatPercent) / 100;
const total = Math.round((subtotal + vat) * 100) / 100;

const pad = (n) => String(n).padStart(2, '0');
const issued = new Date();
const due = new Date(issued.getTime() + termsDays * 86400000);
const stamp = `${issued.getFullYear()}${pad(issued.getMonth() + 1)}${pad(issued.getDate())}`;
const show = (d) => d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });

return [{
  json: {
    seller_name: item.seller_name,
    seller_address: item.seller_address,
    footer_note: item.footer_note,
    customer_name: body.customer_name,
    customer_email: body.customer_email || '',
    invoice_number: body.invoice_number || `INV-${stamp}-1`,
    issue_date: show(issued),
    due_date: show(due),
    currency,
    vat_percent: vatPercent,
    rows,
    subtotal,
    subtotal_display: money(subtotal),
    vat,
    vat_display: money(vat),
    total,
    total_display: money(total),
  },
}];

